public final class ExampleTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Tool(name = "echo_text", description = "Returns the supplied text.")
  public java.lang.String echo(@org.machanism.machai.ai.tools.Param(name = "text", description = "Text to echo.") java.lang.String text) {
    return text;
  }
}
org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", null);
provider.addTools(new ExampleTools());

public final class PromptTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Prompt(name = "project_style", description = "Project answer style.", role = org.machanism.machai.ai.tools.Role.USER)
  public java.lang.String projectStyle() {
    return "Use concise, implementation-focused explanations.";
  }
}
org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", null);
provider.addPrompts(new PromptTools());

// Install dependency in Maven:
// <dependency><groupId>org.machanism.machai</groupId><artifactId>genai-client</artifactId><version>1.2.2</version></dependency>
// Configure ServiceLoader file: src/main/resources/META-INF/services/org.machanism.machai.ai.tools.FunctionTools
// File content: com.example.tools.ProjectTools
org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", null);
org.machanism.machai.ai.tools.FunctionToolsLoader loader = new org.machanism.machai.ai.tools.FunctionToolsLoader();
loader.applyTools(provider, com.example.Application.class);

org.machanism.machai.ai.manager.UsageStatistics.init();
