java.util.List<org.machanism.machai.ai.manager.Usage> usage = org.machanism.machai.ai.manager.UsageStatistics.getUsageForModel("OpenAI:gpt-4o-mini");
org.machanism.machai.ai.manager.UsageStatistics.logUsageForModel("OpenAI:gpt-4o-mini");

public final class ProjectTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Tool(name = "read_project_note", description = "Returns a project note.")
  public java.lang.String readProjectNote(@org.machanism.machai.ai.tools.Param(name = "name", description = "Note name.") java.lang.String name) {
    return "note:" + name;
